for (const chapter of nervousSystemModule.chapters) {
  const supplement = pptSupplementSections[chapter.id];
  if (supplement) {
    chapter.sections.push(...supplement);
  }

  const fullSlideSections = pptFullSlideSections[chapter.id];
  if (fullSlideSections) {
    chapter.sections.push(...fullSlideSections);
  }
}

nervousSystemModule.highFrequencyPoints.push(
  "有髓神经纤维由髓鞘和神经膜共同包被，无髓神经纤维仅由神经膜包被。",
  "突触由突触前部、突触间隙和突触后部构成。",
  "Rexed 板层 I 为边缘层，II 为胶状质，VII 为中间带，IX 为前角运动神经元，X 为中央灰质。",
  "孤束核头端接受味觉，其余部分接受一般内脏感觉。",
  "腹后外侧核接受躯干四肢感觉，腹后内侧核接受头面部感觉和味觉。",
  "内侧膝状体与听觉有关，外侧膝状体与视觉有关。",
  "侧脑室分前角、中央部、后角和下角，借室间孔与第三脑室相通。",
  "视交叉中间部损伤导致双颞侧偏盲，视束以后损伤导致对侧同向性偏盲。",
  "左迷走神经形成前干，右迷走神经形成后干。",
  "大脑中动脉中央支累及内囊可出现三偏综合征。"
);

